<script setup>
import { computed, onMounted, onUnmounted, watch } from 'vue'
import { useRoute } from 'vue-router'
import '../assets/landing.css'
import SiteNav from '../components/landing/SiteNav.vue'
import SiteFooter from '../components/landing/SiteFooter.vue'
import GooeyButton from '../components/GooeyButton.vue'
import EditorialArt from '../components/landing/EditorialArt.vue'
import BlogCard from '../components/landing/BlogCard.vue'
import { BLOG_POSTS, formatPostDate } from '../data/blog'

const route = useRoute()
const post = computed(() => BLOG_POSTS.find(item => item.slug === route.params.slug))
const related = computed(() => BLOG_POSTS.filter(item => item.slug !== post.value?.slug).sort((a, b) => Number(b.category === post.value?.category) - Number(a.category === post.value?.category)).slice(0, 3))
let previousTitle
function updateTitle() { document.title = post.value ? `${post.value.title} | Blog Novexo` : 'Publicação não encontrada | Blog Novexo' }
watch(post, updateTitle)
onMounted(() => { previousTitle = document.title; updateTitle() })
onUnmounted(() => { document.title = previousTitle })
</script>

<template>
  <div id="topo" class="lp story">
    <a class="story__skip" href="#artigo">Pular para o artigo</a>
    <SiteNav />
    <main v-if="post" class="story__main">
      <nav class="story__crumbs" aria-label="Caminho da página"><RouterLink to="/">Início</RouterLink><span aria-hidden="true">/</span><RouterLink to="/blog">Blog</RouterLink><span aria-hidden="true">/</span><span aria-current="page">{{ post.category }}</span></nav>
      <header class="story__header"><div class="story__intro"><h1>{{ post.title }}</h1><p>{{ post.excerpt }}</p><div class="story__author"><span aria-hidden="true">N</span><div><strong>Equipe Novexo</strong><time :datetime="post.date">{{ formatPostDate(post.date) }}</time></div></div></div><div class="story__cover"><EditorialArt :kind="post.art" :lines="post.coverLine" :label="post.coverLabel" /></div></header>

      <div class="story__layout"><aside class="story__sidebar"><div><span class="story__kicker">NESTA LEITURA</span><nav aria-label="Índice do artigo"><a v-for="(section, index) in post.sections" :key="section.title" :href="`#secao-${index + 1}`"><span>{{ String(index + 1).padStart(2, '0') }}</span>{{ section.title }}</a></nav><RouterLink to="/blog" class="story__back">← Todas as publicações</RouterLink></div></aside><article id="artigo" class="story__body"><section v-for="(section, index) in post.sections" :id="`secao-${index + 1}`" :key="section.title"><span class="story__number">{{ String(index + 1).padStart(2, '0') }} / {{ String(post.sections.length).padStart(2, '0') }}</span><h2>{{ section.title }}</h2><p v-for="paragraph in section.text" :key="paragraph">{{ paragraph }}</p></section><div class="story__closing"><span class="story__kicker">UM PRÓXIMO PASSO POSSÍVEL</span><h2>Leve uma boa ideia<br><em>para a sua rotina.</em></h2><p>Conheça o Novexo e encontre um espaço para organizar seu próximo projeto.</p><GooeyButton variant="primary" to="/blog/como-funciona">Veja como funciona <span aria-hidden="true">↗</span></GooeyButton></div></article></div>

      <section class="story__related" aria-labelledby="related-title"><div><h2 id="related-title">A conversa <em>continua.</em></h2><RouterLink to="/blog">Explorar o blog ↗</RouterLink></div><div class="story__grid"><BlogCard v-for="item in related" :key="item.slug" :post="item" /></div></section>
    </main>
    <main v-else id="artigo" class="story__missing"><span class="story__kicker">NOVEXO JOURNAL / 404</span><h1>Essa leitura ainda<br>não está por aqui.</h1><p>Explore o blog para encontrar outras ideias e próximos passos.</p><GooeyButton to="/blog" variant="primary">Voltar ao blog ↗</GooeyButton></main>
    <SiteFooter />
  </div>
</template>

